const newItems = [];

// A list of domains to ignore
const ignoreDomains = [
  'yelp.com',
  'tripadvisor.com',
  'sanantonioreport.org',
  'sanantoniomag.com',
  'expressnews.com',
  'facebook.com',
  'instagram.com',
  'youtube.com',
  'linkedin.com'
];

// Get the array of organic results from the SerpApi node
const results = items[0].json.organic_results;

// Loop through each result
for (const result of results) {
  if (result.link) {

    // Simpler check for ignored domains
    let shouldIgnore = false;
    for (const ignoreDomain of ignoreDomains) {
      if (result.link.includes(ignoreDomain)) {
        shouldIgnore = true;
        break;
      }
    }

    // If the URL is NOT in the ignore list, we keep it
    if (!shouldIgnore) {
      newItems.push({
        json: {
          "title": result.title,
          "url_to_scrape": result.link
        }
      });
    }
  }
}

return newItems;

